package io.aetheris.orchestrator.trading;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="aetheris_paper_trade_journal") public class PaperJournalEntity {@Id private UUID id;@Column(length=40) private String symbol;@Column(nullable=false,length=60) private String eventType;@Column(nullable=false,length=4000) private String detail;private Double pnl;@Column(nullable=false) private Instant createdAt;protected PaperJournalEntity(){}public PaperJournalEntity(UUID id,String symbol,String eventType,String detail,Double pnl){this.id=id;this.symbol=symbol;this.eventType=eventType;this.detail=detail;this.pnl=pnl;this.createdAt=Instant.now();}public UUID getId(){return id;}public String getSymbol(){return symbol;}public String getEventType(){return eventType;}public String getDetail(){return detail;}public Double getPnl(){return pnl;}public Instant getCreatedAt(){return createdAt;}}
